// An in-memory task store.
function normaliseTags(tags) {
  if (!Array.isArray(tags)) return [];
  const result = [];
  for (const value of tags) {
    const tag = String(value).trim().toLowerCase();
    if (tag && !result.includes(tag)) result.push(tag);
  }
  return result;
}

export function createStore() {
  const tasks = [];
  let nextId = 1;
  return {
    add(title, options = {}) {
      const task = {
        id: nextId++,
        title,
        done: false,
        tags: normaliseTags(options.tags),
      };
      tasks.push(task);
      return { ...task, tags: [...task.tags] };
    },
    complete(id) {
      const task = tasks.find((item) => item.id === id);
      if (!task) throw new Error('No task ' + id);
      task.done = true;
      return { ...task, tags: [...task.tags] };
    },
    list(options = {}) {
      const wanted =
        options && options.tag !== undefined && options.tag !== null
          ? String(options.tag).trim().toLowerCase()
          : undefined;
      return tasks
        .filter((task) => wanted === undefined || task.tags.includes(wanted))
        .map((task) => ({ ...task, tags: [...task.tags] }));
    },
  };
}

export function formatTask(task) {
  const tags = Array.isArray(task.tags) ? task.tags : [];
  const suffix = tags.map((tag) => ' #' + tag).join('');
  return (task.done ? '[x]' : '[ ]') + ' ' + task.id + ' ' + task.title + suffix;
}

import { formatTask } from './format.js';

// Splits arguments into a positional title and repeated --tag values.
function parseArgs(args) {
  const positional = [];
  const tags = [];
  for (let index = 0; index < args.length; index += 1) {
    const arg = args[index];
    if (arg === '--tag') {
      const value = args[index + 1];
      if (value === undefined || value.startsWith('--')) {
        throw new Error('--tag needs a value');
      }
      tags.push(value);
      index += 1;
    } else if (arg.startsWith('--')) {
      throw new Error('Unknown option: ' + arg);
    } else {
      positional.push(arg);
    }
  }
  return { positional, tags };
}

// Runs one command and returns the lines to print.
export function run(store, argv) {
  const [command, ...rest] = argv;
  if (command === 'add') {
    const { positional, tags } = parseArgs(rest);
    return [formatTask(store.add(positional.join(' '), { tags }))];
  }
  if (command === 'done') {
    const { positional } = parseArgs(rest);
    return [formatTask(store.complete(Number(positional[0])))];
  }
  if (command === 'list') {
    const { tags } = parseArgs(rest);
    const options = tags.length > 0 ? { tag: tags[0] } : {};
    return store.list(options).map(formatTask);
  }
  throw new Error('Unknown command: ' + command);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { createStore } from '../src/store.js';
import { formatTask } from '../src/format.js';
import { run } from '../src/cli.js';

test('add and complete', () => {
  const store = createStore();
  const task = store.add('Buy milk');
  assert.equal(store.complete(task.id).done, true);
});

test('every task has a tags array, empty when none given', () => {
  const store = createStore();
  const task = store.add('Buy milk');
  assert.deepEqual(task.tags, []);
  assert.deepEqual(store.list()[0].tags, []);
  assert.deepEqual(store.add('Plain', {}).tags, []);
});

test('tags are trimmed, lower-cased and de-duplicated', () => {
  const store = createStore();
  const task = store.add('Buy milk', { tags: ['  Home ', 'home', 'ERRAND'] });
  assert.deepEqual(task.tags, ['home', 'errand']);
});

test('list without a tag returns every task', () => {
  const store = createStore();
  store.add('One', { tags: ['home'] });
  store.add('Two');
  assert.equal(store.list().length, 2);
});

test('list filters by tag without regard to case', () => {
  const store = createStore();
  const first = store.add('One', { tags: ['home', 'errand'] });
  store.add('Two', { tags: ['work'] });
  assert.deepEqual(
    store.list({ tag: 'HOME' }).map((task) => task.id),
    [first.id],
  );
  assert.deepEqual(
    store.list({ tag: '  Errand ' }).map((task) => task.id),
    [first.id],
  );
  assert.deepEqual(store.list({ tag: 'missing' }), []);
});

test('formatTask appends tags after the title', () => {
  const store = createStore();
  const tagged = store.add('Buy milk', { tags: ['home', 'errand'] });
  assert.equal(formatTask(tagged), '[ ] 1 Buy milk #home #errand');
  const plain = store.add('Plain');
  assert.equal(formatTask(plain), '[ ] 2 Plain');
});

test('cli add accepts repeated --tag flags', () => {
  const store = createStore();
  const lines = run(store, ['add', 'Buy', 'milk', '--tag', 'home', '--tag', 'errand']);
  assert.deepEqual(lines, ['[ ] 1 Buy milk #home #errand']);
  assert.deepEqual(store.list()[0].tags, ['home', 'errand']);
});

test('cli list --tag filters', () => {
  const store = createStore();
  run(store, ['add', 'Buy milk', '--tag', 'home']);
  run(store, ['add', 'Ship code', '--tag', 'work']);
  assert.deepEqual(run(store, ['list', '--tag', 'home']), ['[ ] 1 Buy milk #home']);
  assert.equal(run(store, ['list']).length, 2);
});

test('cli rejects unknown options', () => {
  const store = createStore();
  assert.throws(() => run(store, ['add', 'Buy milk', '--x']), (error) => {
    assert.equal(error.message, 'Unknown option: --x');
    return true;
  });
  assert.throws(() => run(store, ['list', '--nope']), /Unknown option: --nope/);
});

test('cli rejects a --tag with no value', () => {
  const store = createStore();
  assert.throws(() => run(store, ['add', 'Buy milk', '--tag']), (error) => {
    assert.equal(error.message, '--tag needs a value');
    return true;
  });
  assert.throws(() => run(store, ['list', '--tag']), /--tag needs a value/);
});
